/* Moodle numerical-question exchange; no external LMS connection is implied. */
(function(root){'use strict';
function xml(value){const text=String(value??'');if(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/.test(text))throw Error('Question text contains characters that XML cannot represent.');return text.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));}
const cdata=value=>'<![CDATA['+String(value).replaceAll(']]>',']]]]><![CDATA[>')+']]>';
function moodle(questions){if(!Array.isArray(questions)||!questions.length||questions.length>500||new Set(questions.map(q=>q.id)).size!==questions.length)throw Error('Choose 1–500 questions with unique identities.');const output=['<?xml version="1.0" encoding="UTF-8"?>','<quiz>'];let chapter=null;
for(const q of questions){if(!Number.isFinite(q.expected)||typeof q.prompt!=='string'||!Array.isArray(q.steps)||!Number.isInteger(q.chapter)||q.chapter<1||q.chapter>16)throw Error('A numerical question is incomplete.');if(q.chapter!==chapter){chapter=q.chapter;output.push('<question type="category"><category><text>$course$/Marine Tools/'+xml(root.MT_TOPICS?.label(chapter)||['Mathematics','Physics','Mechanics','Machine elements','Chemistry','Electrical engineering','Electronics and telecommunications','Power electronics','Engine theory','Steam theory','Heat and flow','Refrigeration','Navigation','Cargo and ship stability','Economics','Corrected displacement'][chapter-1])+'</text></category></question>');}const tolerance=Math.max(q.tolerance??0,Math.abs(q.expected)*(q.relativeTolerance??.001));if(!Number.isFinite(tolerance)||tolerance<0)throw Error('A question has invalid answer tolerance.');const prompt='<p>'+xml(root.MT_I18N?.t(q.prompt)||q.prompt)+'</p>'+(q.unit?'<p>'+xml(root.MT_I18N?.t('Answer unit')||'Answer unit')+': '+xml(root.MT_I18N?.t(q.unit)||q.unit)+'. '+xml(root.MT_I18N?.t('Enter the numerical value.')||'Enter the numerical value.')+'</p>':''),feedback='<ol>'+q.steps.map(s=>'<li>'+xml(root.MT_I18N?.t(s)||s)+'</li>').join('')+'</ol>';
output.push('<question type="numerical"><name><text>'+xml(root.MT_I18N?.t(q.topic||q.id)||q.topic||q.id)+'</text></name><idnumber>'+xml(q.id)+'</idnumber><questiontext format="html"><text>'+cdata(prompt)+'</text></questiontext><generalfeedback format="html"><text>'+cdata(feedback)+'</text></generalfeedback><defaultgrade>1</defaultgrade><penalty>0</penalty><hidden>0</hidden><answer fraction="100"><text>'+q.expected+'</text><tolerance>'+tolerance+'</tolerance><feedback format="html"><text>'+cdata('<p>'+xml(root.MT_I18N?.t('Correct within the stated numerical tolerance.')||'Correct within the stated numerical tolerance.')+'</p>')+'</text></feedback></answer><unitgradingtype>0</unitgradingtype><unitpenalty>0</unitpenalty><showunits>3</showunits><unitsleft>0</unitsleft></question>');}
output.push('</quiz>');return output.join('\n')+'\n';}
root.MT_LMS={moodle};
})(typeof window==='undefined'?globalThis:window);
